const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SEED=[['global','全球宏观观察：利率预期如何影响风险资产？','演示情报，用于展示事件流布局。这不是实时新闻或投资建议。','宏观'],['crypto','比特币生态观察：链上活动与资金流向','演示样例：通过原始来源核验链上指标，关注数据时间与口径。','加密'],['x','X 热门议题观察：AI 与加密基础设施','演示社交事件：热门讨论不能代替事实核验。','社交'],['truth','Truth Social 关注人物动态','演示内容：正式接入需合法的数据源或授权提供商。','政治'],['crypto','以太坊生态：开发进展与应用采用率','演示样例，展示多来源事件聚合。','加密'],['global','全球能源观察：供需变化与市场传导','演示内容，真实事件将保留来源链接和采集时间。','宏观']].map((r,i)=>({id:'demo-'+i,source:r[0],title:r[1],body:r[2],category:r[3],demo:1,url:'',published_at:Math.floor(Date.now()/1000)-i*240}));
let state={events:SEED,drafts:[],watch:new Set(JSON.parse(localStorage.getItem('atlas-watch')||'[]')),source:'',q:'',page:'feed',selected:null,paused:false,connected:false,api:'',token:'',status:{mode:'demo',sources:[],channels:[],ai_configured:false}};
const labels={global:'全球观察',crypto:'加密观察',x:'X / Social',truth:'Truth Social',rss:'RSS / News'};const symbols={global:'◎',crypto:'₿',x:'𝕏',truth:'T',rss:'◫'};
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,options={}){const r=await fetch(state.api+'/api'+path,{...options,headers:{'Authorization':'Bearer '+state.token,'Content-Type':'application/json',...options.headers}});let data;try{data=await r.json()}catch{throw Error('服务器响应格式异常')}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'操作失败，请检查内容或配置');return data}
function time(t){return new Date(t*1000).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}
function renderEvents(){const arr=state.events.filter(e=>(!state.source||e.source===state.source)&&(!state.q||(`${e.title} ${e.body}`).toLowerCase().includes(state.q))&&(state.page!=='watch'||state.watch.has(e.id)));$('#feed-size').textContent=String(arr.length).padStart(2,'0');$('#event-count').textContent=state.events.length;$('#watch-count').textContent=state.watch.size;$('#event-list').innerHTML=arr.length?arr.map(e=>`<article class="event ${state.selected?.id===e.id?'chosen':''}" data-event="${esc(e.id)}" tabindex="0" role="button" aria-label="${esc(e.title)}"><span class="source-icon ${esc(e.source)}">${symbols[e.source]||'◫'}</span><div class="event-main"><div class="event-top"><span>${esc(labels[e.source]||e.source)}</span><span>·</span><span>${time(e.published_at)}</span><span class="tag">${esc(e.category)}</span>${e.demo?'<span class="sample">DEMO</span>':''}</div><h3>${esc(e.title)}</h3><p>${esc(e.body.replace(/<[^>]*>/g,''))}</p><div class="event-meta"><span>↗ ${e.demo?'演示信号':'原始来源'}</span><span>${e.demo?'未核验 · 样例内容':'待核验 · '+new Date(e.published_at*1000).toLocaleDateString('zh-CN')}</span></div></div><button class="watch-btn ${state.watch.has(e.id)?'saved':''}" data-watch="${esc(e.id)}" title="关注事件" aria-label="关注事件">${state.watch.has(e.id)?'★':'☆'}</button></article>`).join(''):'<div class="empty">没有匹配的事件<br><small>尝试其他来源或关键词</small></div>'}
function renderStats(){const n=state.drafts.filter(d=>d.status==='draft').length;$('#draft-count').textContent=state.drafts.length;$('#pending-count').textContent=n;$('#source-state').textContent=state.status.mode==='demo'?'演示':state.status.sources.filter(s=>s.status==='connected').length+' 在线';$('#source-detail').textContent=state.status.mode==='demo'?'未连接真实数据':'已连接后端';$('#latency').textContent=state.connected?'每 5 秒同步事件列表':'等待配置数据源';$('#demo-banner').classList.toggle('hidden',state.connected&&state.status.mode==='live');$('#mode').textContent=state.status.mode==='live'?'LIVE WORKSPACE':'DEMO MODE';$('#connection-label').textContent=state.connected?'后端已连接':'演示工作空间';$('#feed-footer-mode').textContent=state.status.mode==='demo'?'演示数据 · 不进行对外发布':'实时采集 · 人工审核发布'}
function setPage(page){state.page=page;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===page));const names={feed:'实时情报',watch:'我的关注',drafts:'发布中心',sources:'数据源与渠道',architecture:'系统架构'};$('#page-label').textContent=names[page];const titles={feed:'让全球动态，成为你的先机',watch:'追踪你关心的每一个信号',drafts:'从洞察到发布，由你掌控',sources:'连接世界的信息入口',architecture:'一条完整的情报生产流水线'};$('#title').textContent=titles[page];$('#feed-page').classList.toggle('hidden',!['feed','watch'].includes(page));$('#other-page').classList.toggle('hidden',['feed','watch'].includes(page));if(['feed','watch'].includes(page))renderEvents();else renderOther()}
function selectEvent(id){const e=state.events.find(e=>e.id===id);if(!e)return;state.selected=e;renderEvents();$('#ai-content').innerHTML=`<span class="tiny-tag">SOURCE CONTEXT</span><h3>${esc(e.title)}</h3><p>${esc(e.body.replace(/<[^>]*>/g,''))}</p>${safeUrl(e.url)?`<a class="source-link" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a>`:'<span class="muted">演示样例 · 无真实来源</span>'}<p>采集与来源信息用于溯源；模型分析仍需人工核验。</p><button class="primary" id="analyse">✧ 生成 AI 解读</button><button class="text-btn" id="event-compose">基于此事件人工创作 →</button>`;$('#analyse').onclick=async()=>{if(!state.connected)return toast('请先连接后端并配置模型 API');const b=$('#analyse');b.disabled=true;b.textContent='正在分析…';try{const a=await api(`/events/${encodeURIComponent(id)}/analysis`,{method:'POST'});if(state.selected?.id!==id)return;$('#ai-content').innerHTML=`<span class="tiny-tag">AI ANALYSIS · 需人工核验</span><h3>核心摘要</h3><p>${esc(a.summary)}</p><h3>影响路径</h3><ul>${a.implications.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>不确定性</h3><ul>${a.uncertainties.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button class="primary" id="ai-draft">生成待审核草稿 →</button>`;$('#ai-draft').onclick=()=>openEditor(a.draft)}catch(e){toast(e.message);if(state.selected?.id===id){b.disabled=false;b.textContent='✧ 重新分析'}}};$('#event-compose').onclick=()=>openEditor(e.title+'\n\n'+e.body.replace(/<[^>]*>/g,''))}
function safeUrl(s){try{return ['https:','http:'].includes(new URL(s).protocol)}catch{return false}}
function openEditor(content=''){if(!$('#editor').open){$('#content').value=content;$('#char-count').textContent=content.length+' / 280 · X';$('#editor').showModal()}}
function renderOther(){const root=$('#other-page');if(state.page==='drafts'){root.innerHTML=`<section class="panel table-panel"><h2>内容工作台 <span class="pill">${state.connected?'服务器持久化':'当前标签页演示'}</span></h2><p class="muted">保存 → 人工审核 → 提交发布。币安、OKX、Truth 当前使用人工导出。</p>${state.drafts.length?state.drafts.map(d=>`<article class="draft-card"><span class="pill">${esc({draft:'待审核',approved:'已审核',partial:'需处理',published:'已发布'}[d.status]||d.status)}</span><p>${esc(d.content)}</p><div class="delivery">${(d.deliveries||[]).map(x=>`${esc(x.channel)}：${esc(x.status)} ${esc(x.error||x.remote_id||'')}`).join('<br>')}</div><div class="actions"><span>${d.channels.map(esc).join(' / ')}</span><button data-action="export" data-id="${esc(d.id)}">导出内容</button>${d.status==='draft'?`<button data-action="approve" data-id="${esc(d.id)}">人工审核通过</button>`:''}${['approved','partial'].includes(d.status)?`<button data-action="publish" data-id="${esc(d.id)}">提交发布</button>`:''}</div></article>`).join(''):'<div class="empty">还没有草稿。点击「创建内容」开始。</div>'}</section>`}else if(state.page==='sources'){const sources=[['RSS / 全球新闻','公开新闻订阅，无需密钥；需配置许可使用的 HTTPS RSS 地址。'],['X / 实时议题','需要读取权限 Bearer Token；按 API 套餐轮询，非零延迟流。'],['Truth Social','需要官方许可或授权数据提供商。当前未实现真实采集。'],['大模型 / AI 分析','OpenAI 或兼容接口：API Key、Base URL 与模型名称。'],['X / 自动发布','需要用户上下文 OAuth 2.0 Token 与 tweet.write 权限。'],['Telegram / 发布','需要 Bot Token 和目标 Chat ID，已实现发布适配器。'],['币安广场 / 内容','需单独确认内容发布权限。当前为人工导出，不使用交易 API 发文。'],['OKX / 内容','需单独确认社区发布 API。当前为人工导出。'],['服务器 / 部署','Docker Compose + Caddy HTTPS + FastAPI + SQLite WAL 持久化。']];root.innerHTML=`<section class="panel table-panel"><h2>接入清单</h2><div class="card-grid">${sources.map(([n,p])=>`<div class="source-card"><h3>${n}</h3><p>${p}</p><span class="pill">${state.connected?'查看下方实际状态':'待配置 / 演示'}</span></div>`).join('')}</div></section><section class="panel table-panel"><h2>实际连接状态</h2><div class="architecture-details">${state.connected?`模型：${state.status.ai_configured?'已配置（仍需请求验证）':'未配置'}<br>${state.status.sources.map(s=>`${esc(s.source)} · ${esc(s.status)} · ${esc(s.error||'')}`).join('<br>')||'尚无采集记录'}<br>${state.status.channels.map(c=>`${esc(c.label)} · ${c.mode==='manual_export'?'人工导出':c.configured?'已配置（待验证）':'未配置'}`).join('<br>')}`:'连接后端后显示真实状态，不会把演示卡片标记为已接入。'}</div></section>`}else root.innerHTML=`<section class="panel table-panel"><h2>系统架构 · v0.1</h2><div class="arch-flow"><div>授权数据源</div>→<div>采集与去重</div>→<div>来源持久化</div>→<div>模型分析</div>→<div>人工审核</div>→<div>渠道发布</div></div><div class="architecture-details">展示层：响应式暗色控制台、搜索、关注、AI 解读、人工创作、草稿审核与渠道状态。<br>API 层：FastAPI，Bearer 管理认证，SSE 事件接口及浏览器轮询。<br>数据层：SQLite WAL，来源 ID 去重，草稿状态机，唯一发布记录和操作审计。<br>采集层：RSS 与 X 轮询，可配置间隔。Truth 采集接口待提供。<br>发布层：X / Telegram API；币安 / OKX / Truth 人工导出，网络结果不确定时人工核验。<br>部署层：Docker Compose + Caddy TLS，服务仅经反向代理公开，数据库持久化卷。<br>扩展阶段：PostgreSQL、Redis 队列、多租户 RBAC、语义聚类、授权流式数据源。</div></section>`}
async function sync(){if(!state.connected)return;try{const [events,drafts,status]=await Promise.all([api('/events'),api('/drafts'),api('/status')]);state.events=events;state.drafts=drafts;state.status=status;renderStats();if(['feed','watch'].includes(state.page))renderEvents();else renderOther()}catch(e){toast(e.message)}}
$('#event-list').onclick=e=>{const w=e.target.closest('[data-watch]');if(w){const id=w.dataset.watch;state.watch.has(id)?state.watch.delete(id):state.watch.add(id);localStorage.setItem('atlas-watch',JSON.stringify([...state.watch]));renderEvents();return}const n=e.target.closest('[data-event]');if(n)selectEvent(n.dataset.event)};$('#event-list').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-event]')){e.preventDefault();selectEvent(e.target.dataset.event)}};
$('#filters').onclick=e=>{const b=e.target.closest('[data-source]');if(!b)return;state.source=b.dataset.source;document.querySelectorAll('[data-source]').forEach(n=>n.classList.toggle('selected',n===b));renderEvents()};$('#search').oninput=e=>{state.q=e.target.value.toLowerCase();renderEvents()};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));['#compose','#compose-side'].forEach(s=>$(s).onclick=()=>{state.selected=null;openEditor()});['#connect-btn','#banner-connect','#mode'].forEach(s=>$(s).onclick=()=>$('#connect-modal').showModal());document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#content').oninput=e=>$('#char-count').textContent=e.target.value.length+' / 280 · X';
$('#editor-form').onsubmit=async e=>{e.preventDefault();const content=$('#content').value.trim();const channels=[...document.querySelectorAll('.channel-picker input:checked')].map(n=>n.value);if(!content||!channels.length)return toast('请填写内容并选择渠道');if(channels.includes('x')&&content.length>280)return toast('X 草稿超过 280 字符，请缩短内容或取消 X 渠道');const body={content,channels,event_id:state.selected?.id||null};try{if(state.connected){await api('/drafts',{method:'POST',body:JSON.stringify(body)});await sync()}else{state.drafts.unshift({...body,id:crypto.randomUUID(),status:'draft',created_at:Date.now()/1000});renderStats()}$('#editor').close();setPage('drafts');toast(state.connected?'草稿已保存到服务器':'演示草稿已保存到当前标签页，刷新会清空')}catch(e){toast(e.message)}};
$('#connection-form').onsubmit=async e=>{e.preventDefault();const url=$('#api-url').value.trim().replace(/\/$/,'');if(url&&(!safeUrl(url)||new URL(url).protocol!=='https:'))return toast('远程后端必须使用 HTTPS');const old={api:state.api,token:state.token};state.api=url;state.token=$('#api-token').value;try{const status=await api('/status');state.connected=true;state.status=status;$('#api-token').value='';$('#connect-modal').close();await sync();toast('后端连接成功')}catch(e){state.api=old.api;state.token=old.token;toast(e.message)}};
$('#other-page').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const d=state.drafts.find(x=>x.id===b.dataset.id);if(!d)return;const action=b.dataset.action;if(action==='export'){const blob=new Blob([d.content],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='signal-atlas-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(action==='publish'&&(!state.connected||state.status.mode==='demo'))return toast('演示模式禁止对外发布，请连接生产后端');b.disabled=true;try{if(state.connected){await api(`/drafts/${d.id}/${action}`,{method:'POST'});await sync()}else{d.status='approved';renderOther();renderStats()}toast(action==='approve'?'人工审核已记录':'提交完成，请查看每个渠道的实际结果')}catch(e){toast(e.message);b.disabled=false}};
$('#refresh').onclick=()=>state.connected?sync():toast('当前为固定演示数据，请连接后端');$('#pause').onclick=()=>{state.paused=!state.paused;$('#pause').textContent=state.paused?'▶ 恢复':'Ⅱ 暂停'};setInterval(()=>{if(state.connected&&!state.paused&&['feed','watch'].includes(state.page))sync()},5000);setInterval(()=>$('#clock').textContent=new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}),1000);renderEvents();renderStats();
